insert into events (id, data) values ('tablig-akbar', '{"id":"tablig-akbar","title":"Tablig Akbar: Menjaga Ukhuwah di Era Digital","date":"2026-11-14","time":"19.30 – 21.30 WIB","speaker":"Ust. Dr. Ahmad Fauzan, Lc., M.A.","category":"Umum","bio":"Dosen dan pendakwah dengan fokus kajian ukhuwah dan media.","location":"Ruang utama masjid","tag":"Kajian akbar","desc":"Kajian kebangsaan tentang cara menjaga persaudaraan di tengah arus informasi digital. Terbuka untuk jamaah umum, ikhwan dan akhwat, dengan area parkir tambahan di halaman sekolah sebelah.","status":"akan"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into events (id, data) values ('kajian-tafsir', '{"id":"kajian-tafsir","title":"Kajian Tafsir: Menyelami Surah Al-Hujurat","date":"2026-11-22","time":"08.00 – 10.00 WIB","speaker":"Ust. Muhammad Ridwan, S.Ag.","category":"Khusus Ikhwan","bio":"Pengajar tafsir di berbagai majelis taklim warga.","location":"Aula lantai 2","tag":"Kajian rutin","desc":"Membahas adab sosial dan menjaga lisan melalui tafsir Surah Al-Hujurat. Peserta disarankan membawa Al-Qur''an dan buku catatan.","status":"akan"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into events (id, data) values ('santunan-yatim', '{"id":"santunan-yatim","title":"Santunan Yatim & Dhuafa Akhir Tahun","date":"2026-12-05","time":"09.00 – 12.00 WIB","speaker":"Panitia Sosial & Ust. Abdurrahman","category":"Umum","bio":"Pembina sosial dan pengurus lembaga amil setempat.","location":"Halaman masjid","tag":"Sosial","desc":"Penyaluran santunan, paket sekolah, dan kebutuhan pokok bagi anak yatim serta keluarga dhuafa binaan masjid. Donatur dapat hadir langsung untuk menyerahkan santunan.","status":"akan"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into events (id, data) values ('mabit-remaja', '{"id":"mabit-remaja","title":"Malam Bina Iman & Taqwa (MABIT) Remaja","date":"2026-12-19","time":"20.00 WIB – 04.30 WIB","speaker":"Ust. Fikri Haikal","category":"Khusus Akhwat","bio":"Pembina remaja masjid dan mentor kajian pemuda.","location":"Masjid & aula","tag":"Remaja","desc":"Malam pembinaan remaja berisi kajian, qiyamul lail, dan kegiatan kelompok. Pendaftaran melalui WhatsApp admin dengan kuota terbatas.","status":"akan"}'::jsonb) on conflict (id) do update set data = excluded.data;
