insert into activities (id, data) values ('kajian-rutin', '{"id":"kajian-rutin","date":"2026-11-02","title":"Kajian Ba''da Maghrib","schedule":"Senin & Kamis · setelah Maghrib","pic":"Seksi Dakwah","desc":"Kajian tematik fiqih dan akhlak bersama ustaz setempat, terbuka untuk jamaah umum dan remaja.","image":{"src":"assets/stock/kajian.jpg","width":1400,"height":933,"alt":"Jamaah membaca Al-Qur''an bersama di dalam masjid."}}'::jsonb) on conflict (id) do update set data = excluded.data;
