insert into activities (id, data) values ('kerja-bakti-rutin', '{"id":"kerja-bakti-rutin","date":"2026-11-07","title":"Kerja Bakti Masjid","schedule":"Sabtu pekan pertama · 07.00 WIB","pic":"Seksi Sarana & Prasarana","desc":"Membersihkan area masjid, merawat taman, dan menyiapkan fasilitas menjelang kegiatan besar.","image":{"src":"assets/stock/bakti-sosial.jpg","width":1400,"height":933,"alt":"Relawan menyortir pakaian dan kebutuhan pokok ke dalam kotak donasi."}}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into articles (id, data) values ('adab-masjid', '{"id":"adab-masjid","title":"Adab Masuk Masjid: Sunnah Kecil yang Menghadirkan Ketenangan","category":"Akhlak","author":"Ust. Muhammad Ridwan, S.Ag.","date":"2026-10-20","read":5,"excerpt":"Masjid bukan hanya tempat sujud, tetapi rumah yang menenangkan. Beberapa adab sederhana membantu kita menjaganya.","image":{"src":"assets/stock/kajian.jpg","width":1400,"height":933,"alt":"Jamaah membaca Al-Qur''an bersama di dalam masjid."},"body":"<p>Memasuki masjid berarti memasuki ruang yang Allah muliakan. Di dalamnya ada sujud, dzikir, dan percakapan yang saling menguatkan. Karena itu, adab yang baik bukan sekadar formalitas, melainkan cara kita menghormati tempat dan orang-orang di dalamnya.</p>\n<p>Beberapa kebiasaan sederhana berikut membantu menjaga ketenangan masjid sekaligus membuat jamaah lain merasa nyaman.</p>\n<ul><li>Mengucapkan salam saat masuk dan keluar masjid.</li><li>Menyenyapkan nada dering sebelum masuk ruang sholat.</li><li>Mendahulukan kaki kanan, lalu berdoa dengan tenang.</li><li>Menjaga kebersihan alas sholat dan membuang sampah pada tempatnya.</li><li>Menghindari percakapan keras ketika jamaah lain sedang sholat atau membaca Al-Qur''an.</li></ul>\n<h2>Adab yang tumbuh dari kesadaran</h2>\n<p>Adab juga mencakup cara kita menyikapi perbedaan. Masjid adalah tempat berkumpulnya warga dengan latar belakang yang beragam. Menyapa tamu, memberi ruang bagi jamaah lanjut usia, dan menahan diri dari perdebatan adalah bagian dari akhlak yang diajarkan Rasulullah SAW.</p>\n<blockquote>Masjid yang nyaman lahir dari jamaah yang saling menjaga, bukan hanya dari bangunan yang megah.</blockquote>\n<p>Mari mulai dari hal kecil: datang lebih awal, sholat dengan tenang, dan pulang dengan hati yang lebih lapang.</p>","status":"terbit"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into articles (id, data) values ('sholat-berjamaah', '{"id":"sholat-berjamaah","title":"Keutamaan Sholat Berjamaah bagi Kehidupan Sosial","category":"Ibadah","author":"Ust. Abdurrahman","date":"2026-10-14","read":6,"excerpt":"Satu shaf mengajarkan kedisiplinan, kesetaraan, dan kepedulian yang sulit ditemukan di tempat lain.","image":null,"body":"<p>Sholat berjamaah bukan hanya ibadah yang lebih utama, tetapi juga latihan sosial yang membentuk karakter. Dalam satu shaf, kita berdiri sejajar tanpa membedakan jabatan, kekayaan, atau asal-usul.</p>\n<h2>Lebih dari sekadar pahala</h2>\n<p>Rasulullah SAW menganjurkan sholat berjamaah karena di dalamnya terdapat kedisiplinan waktu, kepatuhan pada imam, dan kepedulian pada jamaah di sekitar kita. Seseorang yang terbiasa datang tepat waktu akan membawa kebiasaan itu ke tempat kerja dan keluarganya.</p>\n<ul><li>Melatih disiplin terhadap waktu dan komitmen.</li><li>Menumbuhkan rasa setara di hadapan Allah.</li><li>Membuka peluang silaturahmi antarwarga.</li><li>Menjadi sarana saling mengenal dan membantu.</li></ul>\n<p>Bagi masjid, jamaah yang hidup adalah kekuatan utama. Semakin sering kita hadir, semakin besar peluang kebaikan yang bisa kita rawat bersama.</p>\n<blockquote>Sholat berjamaah mengajarkan bahwa kebaikan tidak dilakukan sendirian.</blockquote>","status":"terbit"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into articles (id, data) values ('jumat-berkah', '{"id":"jumat-berkah","title":"Jumat Berkah: Ketika Sepiring Makan Siang Menjadi Jembatan","category":"Berita","author":"Seksi Sosial & Kemaslahatan","date":"2026-10-11","read":4,"excerpt":"Seusai sholat Jumat, dapur masjid bekerja untuk jamaah dan warga yang membutuhkan. Begitulah kepedulian dirawat.","image":{"src":"assets/stock/jumat-berkah.jpg","width":1400,"height":933,"alt":"Warga berkumpul dan menyiapkan makanan bersama dalam kegiatan sosial."},"body":"<p>Seusai sholat Jumat, aroma makanan dari dapur masjid menandakan program Jum''at Berkah dimulai. Porsi makan siang disiapkan oleh relawan, lalu dibagikan kepada jamaah, pekerja jalan, dan warga yang membutuhkan.</p>\n<p>Program ini lahir dari kebiasaan sederhana warga: berbagi kepada siapa pun yang hadir, tanpa bertanya dari mana asalnya. Sebagian jamaah membawa lauk tambahan, sebagian lain membantu memasak dan membagikan.</p>\n<blockquote>Yang dibagikan bukan hanya makanan, tetapi rasa bahwa tidak ada warga yang berjuang sendirian.</blockquote>\n<p>Bagi yang ingin terlibat, kontribusi dapat disalurkan melalui program Donasi Umum atau langsung kepada koordinator kegiatan saat hari Jumat. Relawan selalu terbuka untuk membantu persiapan dan distribusi.</p>","status":"terbit"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into articles (id, data) values ('transparansi-donasi', '{"id":"transparansi-donasi","title":"Menjaga Amanah Donasi: Transparansi sebagai Bagian dari Ibadah","category":"Berita","author":"Bendahara DKM","date":"2026-10-06","read":4,"excerpt":"Donasi yang dipercayakan jamaah bukan sekadar angka. Ada amanah yang harus dicatat, diverifikasi, dan dilaporkan.","image":{"src":"assets/stock/bakti-sosial.jpg","width":1400,"height":933,"alt":"Relawan menyortir pakaian dan kebutuhan pokok ke dalam kotak donasi."},"body":"<p>Setiap donasi yang masuk ke masjid adalah amanah. Karena itu, pengurus mencatat setiap transaksi, memverifikasi bukti transfer, dan melaporkan penyalurannya kepada jamaah secara berkala.</p>\n<h2>Alur yang dijaga</h2>\n<ul><li>Donasi diterima melalui rekening resmi, QRIS, atau sekretariat masjid.</li><li>Admin mencatat nama, nominal, program, dan tanggal donasi.</li><li>Bukti transfer diverifikasi sebelum status diubah menjadi terverifikasi.</li><li>Laporan penyaluran disusun sesuai program dan dipublikasikan melalui halaman donasi.</li></ul>\n<p>Donatur yang ingin tampil anonim tetap dapat memantau laporannya. Nama mereka akan ditampilkan sebagai \"Hamba Allah\" atau tidak dicantumkan sama sekali.</p>\n<p>Transparansi bukan tanda ketidakpercayaan, melainkan bentuk saling menjaga. Dengan begitu, kepercayaan jamaah dapat terus tumbuh dan program kebaikan bisa berjalan lebih panjang.</p>","status":"terbit"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into articles (id, data) values ('tiga-amalan-ringan', '{"id":"tiga-amalan-ringan","title":"Tiga Amalan Ringan yang Berpahala Besar","category":"Hadis","author":"Ust. Fikri Haikal","date":"2026-09-28","read":5,"excerpt":"Kebaikan tidak selalu menuntut banyak biaya. Ada amalan sederhana yang dapat dilakukan setiap hari.","image":null,"body":"<p>Kadang kita menunggu kesempatan besar untuk berbuat baik. Padahal, Rasulullah SAW mengajarkan bahwa amalan ringan yang dilakukan dengan konsisten memiliki nilai besar di sisi Allah.</p>\n<h2>Tersenyum kepada saudara</h2>\n<p>Senyum sederhana dapat mencairkan ketegangan dan menyampaikan rasa hormat. Di masjid, senyum kepada jamaah baru atau tamu bisa membuat mereka merasa diterima.</p>\n<h2>Menyingkirkan gangguan di jalan</h2>\n<p>Memindahkan batu, dahan, atau sampah dari jalan bukan perkara sepele. Tindakan kecil ini menjaga orang lain dari bahaya dan menunjukkan kepedulian terhadap ruang bersama.</p>\n<h2>Membaca Al-Qur''an meski satu ayat</h2>\n<p>Membaca satu ayat setiap hari lebih baik daripada menunggu waktu luang yang panjang. Kebiasaan kecil ini menjaga hubungan dengan kitab Allah dan menenangkan hati.</p>\n<blockquote>Konsistensi lebih berharga daripada banyaknya amalan yang kemudian berhenti.</blockquote>\n<p>Mari memilih satu amalan ringan untuk dimulai hari ini, lalu menjaganya agar tetap berjalan.</p>","status":"terbit"}'::jsonb) on conflict (id) do update set data = excluded.data;
insert into articles (id, data) values ('laporan-santunan', '{"id":"laporan-santunan","title":"Santunan Yatim & Dhuafa: Laporan Kegiatan bulan September","category":"Berita","author":"Panitia Sosial","date":"2026-09-21","read":3,"excerpt":"Penyaluran santunan bulanan berjalan bersama relawan warga. Terima kasih kepada seluruh donatur.","image":{"src":"assets/stock/bakti-sosial.jpg","width":1400,"height":933,"alt":"Relawan menyortir pakaian dan kebutuhan pokok ke dalam kotak donasi."},"body":"<p>Program santunan yatim dan dhuafa bulan September telah dilaksanakan di halaman masjid. Paket kebutuhan pokok dan bantuan pendidikan diserahkan kepada keluarga binaan yang telah terdata oleh seksi sosial.</p>\n<p>Kegiatan diawali dengan tausiyah singkat, lalu dilanjutkan dengan penyerahan santunan dan ramah tamah bersama warga. Relawan juga mendampingi keluarga yang membutuhkan pendampingan administrasi sekolah.</p>\n<p>Laporan rinci penerimaan dan penyaluran dapat dilihat pada halaman donasi. Donatur yang ingin berpartisipasi pada penyaluran berikutnya dapat menghubungi admin melalui WhatsApp.</p>","status":"terbit"}'::jsonb) on conflict (id) do update set data = excluded.data;
